-- Event evidence. Excerpts are source wording, never internal event labels.
insert into knowledge.claim_evidence (id, claim_id, source_id, relationship, locator, excerpt)
select
    ('61000000-0000-4000-8000-' || right(claim.id::text, 12))::uuid,
    claim.id,
    case when claim.asserted_by_agent_id = '10000000-0000-4000-8000-000000000001'::uuid
         then '41000000-0000-4000-8000-000000000001'::uuid
         else '41000000-0000-4000-8000-000000000002'::uuid end,
    'supports',
    case when claim.asserted_by_agent_id = '10000000-0000-4000-8000-000000000001'::uuid
         then 'Provenance field > Paula account'
         else 'Provenance history paragraph' end,
    case
        when claim.id between '51000000-0000-4000-8000-000000000020'::uuid and '51000000-0000-4000-8000-000000000024'::uuid
            then 'sacado por el Padre Hippolyte Roussel desde Rapa Nui a Tahiti'
        when claim.id between '51000000-0000-4000-8000-000000000025'::uuid and '51000000-0000-4000-8000-000000000028'::uuid
            then 'entregada al arzobispo Tepano Jaussen'
        when claim.id between '51000000-0000-4000-8000-000000000030'::uuid and '51000000-0000-4000-8000-000000000034'::uuid
            then 'apparently collected by Gaspar Zumbohm in 1870'
        when claim.id between '51000000-0000-4000-8000-000000000035'::uuid and '51000000-0000-4000-8000-000000000039'::uuid
            then 'sent to him in Tahiti'
        when claim.id in (
            '51000000-0000-4000-8000-000000000041'::uuid,
            '51000000-0000-4000-8000-000000000046'::uuid
        ) then null
        when claim.id between '51000000-0000-4000-8000-000000000040'::uuid and '51000000-0000-4000-8000-000000000044'::uuid
          or claim.id = '51000000-0000-4000-8000-000000000069'::uuid
            then 'deposited in the Missionary Museum, either by Jaussen in 1888 or by the French navy in 1892 after his death'
        when claim.id between '51000000-0000-4000-8000-000000000045'::uuid and '51000000-0000-4000-8000-000000000049'::uuid
          or claim.id = '51000000-0000-4000-8000-000000000070'::uuid
            then 'deposited in the Missionary Museum, either by Jaussen in 1888 or by the French navy in 1892 after his death'
        else null
    end
from knowledge.claim as claim
where claim.subject_id >= '81000000-0000-4000-8000-000000000001'::uuid
  and claim.subject_id <= '81000000-0000-4000-8000-000000000009'::uuid;

